import {
  createContext,
  useContext,
  useState,
  useEffect,
  useCallback,
} from 'react'
import type { ReactNode } from 'react'
import { createAuthAdapter } from '../adapter'
import type { AuthUser, AuthError, AuthResult } from '../types'

interface AuthContextValue {
  user: AuthUser | null
  loading: boolean
  error: AuthError | null
  signInWithEmail: (email: string, password: string) => Promise<AuthResult>
  signUpWithEmail: (
    email: string,
    password: string,
    firstName: string,
    lastName: string
  ) => Promise<AuthResult>
  signOut: () => Promise<void>
}

const AuthContext = createContext<AuthContextValue | null>(null)

const adapter = createAuthAdapter()

interface Props {
  children: ReactNode
}

export function AuthProvider({ children }: Props) {
  const [user, setUser] = useState<AuthUser | null>(
    adapter.getCurrentUser()
  )
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<AuthError | null>(null)

  useEffect(() => {
    const unsubscribe = adapter.onAuthStateChanged((u) => {
      setUser(u)
      setLoading(false)
    })

    return unsubscribe
  }, [])

  const signInWithEmail = useCallback(
    async (email: string, password: string) => {
      setError(null)

      const result = await adapter.signInWithEmail(email, password)

      if (!result.success && result.error) {
        setError(result.error)
      }

      return result
    },
    []
  )

  const signUpWithEmail = useCallback(
    async (
      email: string,
      password: string,
      firstName: string,
      lastName: string
    ) => {
      setError(null)

      const result = await adapter.signUpWithEmail(
        email,
        password,
        firstName,
        lastName
      )

      if (!result.success && result.error) {
        setError(result.error)
      }

      return result
    },
    []
  )

  const signOut = useCallback(async () => {
    setError(null)
    await adapter.signOut()
  }, [])

  return (
    <AuthContext.Provider
      value={{
        user,
        loading,
        error,
        signInWithEmail,
        signUpWithEmail,
        signOut,
      }}
    >
      {children}
    </AuthContext.Provider>
  )
}

export function useAuthContext() {
  const context = useContext(AuthContext)

  if (!context) {
    throw new Error('useAuthContext must be used within an AuthProvider')
  }

  return context
}